using System.ComponentModel.DataAnnotations;
namespace SimplexLawFirm.Models;
public sealed class ExternalEvidenceRequest { public long Id { get; set; } public int CaseId { get; set; } public Case Case { get; set; } = null!; [MaxLength(254)] public string RecipientEmail { get; set; } = ""; [MaxLength(150)] public string RecipientName { get; set; } = ""; [MaxLength(64)] public string TokenHash { get; set; } = ""; public DateTime CreatedAtUtc { get; set; } = DateTime.UtcNow; public DateTime ExpiresAtUtc { get; set; } public DateTime? AccessedAtUtc { get; set; } public DateTime? ClosedAtUtc { get; set; } public DateTime? RevokedAtUtc { get; set; } public int RequestedByUserId { get; set; } public ICollection<ExternalEvidenceDocument> Documents { get; set; } = []; }
public sealed class ExternalEvidenceDocument { public long Id { get; set; } public long RequestId { get; set; } public ExternalEvidenceRequest Request { get; set; } = null!; [MaxLength(200)] public string OriginalFileName { get; set; } = ""; [MaxLength(2500)] public string Purpose { get; set; } = ""; [MaxLength(80)] public string? RequirementCode { get; set; } [MaxLength(500)] public string RelativePath { get; set; } = ""; [MaxLength(100)] public string ContentType { get; set; } = ""; public long SizeBytes { get; set; } public string Sha256Hash { get; set; } = ""; public DateTime UploadedAtUtc { get; set; } = DateTime.UtcNow; }
